/* ─── 新鲜度检查 ─── */


新鲜度检查
>100ms → F_x=0

/* Arrow within CPG: 新鲜度 → Hopf */


/* ─── Hopf CPG 振荡器 ─── */


Hopf CPG 振荡器
r²=x²+y²
dx=α(μ-r²)x-ωy+ε·F
dy=α(μ-r²)y+ωx
α=10 μ=1 ω≈0.9Hz ε=0.01

/* Arrow within CPG: Hopf → 变导纳 */


/* ─── 变导纳控制 ─── */


变导纳控制
D=D_base-λ·x [15,80]
M·a+D·v=F_ext
M=15 D_base=40 λ=20

/* Arrow within CPG: 变导纳 → v_c */


/* ─── v_c 输出 m/s ─── */


v_c 速度指令
[-0.5, 1.2] m/s

/* Arrow within CPG: v_c → m/s→rpm */


/* ─── m/s → rpm ─── */


m/s → rpm
rpm=v×60/(2π×0.075)

/* Arrow within CPG: rpm → 限幅 */


/* ─── 限幅 ─── */


clamp ±400 rpm
左+rpm 右-rpm

/* Final output from ControlTask */


/* ─── MotorCmd 输出 ─── */


MCQ
8×24B

/* Arrow: MotorCmdQueue → MotorTxTask */


/* Arrow from main flow entering ControlTask */
Controller_Run(fx, dt=0.001)

